package com.example.job_service.entity; import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="job_locations") public class Location{@Id private UUID id;private String name;private String slug;private boolean active;@Column(name="created_at")private Instant createdAt;@Column(name="updated_at")private Instant updatedAt;protected Location(){}public Location(String n,String s){id=UUID.randomUUID();name=n;slug=s;active=true;createdAt=Instant.now();updatedAt=createdAt;}public UUID getId(){return id;}public String getName(){return name;}public String getSlug(){return slug;}public boolean isActive(){return active;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
